//! Per-state block collision and outline shapes.
//!
//! `assets/block_shapes.tsv.gz` is generated by
//! `scripts/extract_block_shapes.ps1` from the local Folia 1.21.11 oracle. It
//! contains one row per registry block state with two semicolon-separated AABB
//! lists: the collision shape (`getCollisionShape`) and the outline/selection
//! shape (`getShape`). Coordinates are block-local and already in world units
//! (0..1 for a normal block, larger for shapes such as fences and walls that
//! extend above their block).
//!
//! States whose block has no collision (air, fluids, plants, torches, ...) are
//! stored as empty lists for both shapes. The objective for this slice is
//! physics, so passable states deliberately do not expose a selection outline;
//! consumers that need a hit box should use [`outline_boxes`] on collidable
//! states only.
//!
//! Unknown or out-of-range state ids fall back to a full cube, matching the
//! conservative full-cube behaviour this port had before shapes were ported.
//! The table is embedded and parsed once; the server never starts a JVM for
//! shapes.

use crate::chunk::BlockState;
use crate::registry;
use flate2::read::GzDecoder;
use std::io::Read;
use std::sync::OnceLock;

const BLOCK_SHAPES: &[u8] = include_bytes!("../assets/block_shapes.tsv.gz");
const STATE_COUNT: usize = 29_671;

/// An axis-aligned box in block-local or world coordinates.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Aabb {
    pub min_x: f64,
    pub min_y: f64,
    pub min_z: f64,
    pub max_x: f64,
    pub max_y: f64,
    pub max_z: f64,
}

impl Aabb {
    /// The unit cube used as the fallback for unknown states.
    pub const FULL: Self = Self::new(0.0, 0.0, 0.0, 1.0, 1.0, 1.0);

    pub const fn new(
        min_x: f64,
        min_y: f64,
        min_z: f64,
        max_x: f64,
        max_y: f64,
        max_z: f64,
    ) -> Self {
        Self {
            min_x,
            min_y,
            min_z,
            max_x,
            max_y,
            max_z,
        }
    }

    /// The full cube occupied by the block at `(x, y, z)`.
    pub fn block(x: i32, y: i32, z: i32) -> Self {
        let min_x = f64::from(x);
        let min_y = f64::from(y);
        let min_z = f64::from(z);
        Self::new(min_x, min_y, min_z, min_x + 1.0, min_y + 1.0, min_z + 1.0)
    }

    /// The box a player with the given feet position and dimensions occupies.
    pub fn player(x: f64, y: f64, z: f64, width: f64, height: f64) -> Self {
        let half = width * 0.5;
        Self::new(x - half, y, z - half, x + half, y + height, z + half)
    }

    pub fn offset(self, x: f64, y: f64, z: f64) -> Self {
        Self::new(
            self.min_x + x,
            self.min_y + y,
            self.min_z + z,
            self.max_x + x,
            self.max_y + y,
            self.max_z + z,
        )
    }

    /// The union of this box and the box translated towards the movement.
    pub fn expand_towards(self, x: f64, y: f64, z: f64) -> Self {
        Self::new(
            self.min_x + x.min(0.0),
            self.min_y + y.min(0.0),
            self.min_z + z.min(0.0),
            self.max_x + x.max(0.0),
            self.max_y + y.max(0.0),
            self.max_z + z.max(0.0),
        )
    }

    /// Strict overlap: boxes that only touch at a face do not count.
    pub fn intersects(self, other: &Aabb) -> bool {
        self.min_x < other.max_x
            && self.max_x > other.min_x
            && self.min_y < other.max_y
            && self.max_y > other.min_y
            && self.min_z < other.max_z
            && self.max_z > other.min_z
    }

    /// Whether any axis has zero or negative extent.
    pub fn is_empty(self) -> bool {
        self.min_x >= self.max_x || self.min_y >= self.max_y || self.min_z >= self.max_z
    }
}

struct ShapeTable {
    collision: Vec<Vec<Aabb>>,
    outline: Vec<Vec<Aabb>>,
}

static TABLE: OnceLock<Result<ShapeTable, String>> = OnceLock::new();

fn parse_shape(text: &str, state_id: usize) -> Result<Vec<Aabb>, String> {
    if text.is_empty() {
        return Ok(Vec::new());
    }
    let mut boxes = Vec::new();
    for (index, raw_box) in text.split(';').enumerate() {
        let values: Vec<&str> = raw_box.split(',').collect();
        if values.len() != 6 {
            return Err(format!(
                "state {state_id} box {index} has {} coordinates",
                values.len()
            ));
        }
        let mut coordinates = [0.0f64; 6];
        for (coordinate, value) in coordinates.iter_mut().zip(&values) {
            *coordinate = value
                .parse::<f64>()
                .map_err(|_| format!("state {state_id} box {index} has invalid '{value}'"))?;
            if !coordinate.is_finite() {
                return Err(format!("state {state_id} box {index} is not finite"));
            }
        }
        let bounds = Aabb::new(
            coordinates[0],
            coordinates[1],
            coordinates[2],
            coordinates[3],
            coordinates[4],
            coordinates[5],
        );
        if bounds.min_x > bounds.max_x || bounds.min_y > bounds.max_y || bounds.min_z > bounds.max_z
        {
            return Err(format!("state {state_id} box {index} is inverted"));
        }
        boxes.push(bounds);
    }
    boxes.sort_by(|left, right| {
        left.min_x
            .total_cmp(&right.min_x)
            .then(left.min_y.total_cmp(&right.min_y))
            .then(left.min_z.total_cmp(&right.min_z))
            .then(left.max_x.total_cmp(&right.max_x))
            .then(left.max_y.total_cmp(&right.max_y))
            .then(left.max_z.total_cmp(&right.max_z))
    });
    boxes.dedup();
    Ok(boxes)
}

fn parse() -> Result<ShapeTable, String> {
    let mut decoder = GzDecoder::new(BLOCK_SHAPES);
    let mut text = String::new();
    decoder
        .read_to_string(&mut text)
        .map_err(|error| format!("cannot decompress block shapes: {error}"))?;

    let mut collision = Vec::with_capacity(STATE_COUNT);
    let mut outline = Vec::with_capacity(STATE_COUNT);
    for (line_index, line) in text.lines().enumerate() {
        if line_index == 0 {
            if line != "id\tcollision\toutline" {
                return Err(format!("unexpected block-shape header '{line}'"));
            }
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        if fields.len() != 3 {
            return Err(format!(
                "block-shape row {line_index} has {} fields",
                fields.len()
            ));
        }
        let state_id: usize = fields[0]
            .parse()
            .map_err(|_| format!("block-shape row {line_index} has invalid id"))?;
        if state_id != collision.len() {
            return Err(format!(
                "block-shape ids are not dense at row {line_index}: found {state_id}, expected {}",
                collision.len()
            ));
        }
        collision.push(parse_shape(fields[1], state_id)?);
        outline.push(parse_shape(fields[2], state_id)?);
    }

    if collision.len() != STATE_COUNT {
        return Err(format!(
            "expected {STATE_COUNT} block-shape rows, found {}",
            collision.len()
        ));
    }
    Ok(ShapeTable { collision, outline })
}

fn table() -> Option<&'static ShapeTable> {
    TABLE.get_or_init(parse).as_ref().ok()
}

static FULL_CUBE: [Aabb; 1] = [Aabb::FULL];

/// Collision boxes for a registry block-state id.
///
/// Unknown ids fall back to a full cube. Known passable states (air, fluids,
/// plants, ...) return an empty slice.
pub fn collision_boxes(state_id: i32) -> &'static [Aabb] {
    let Ok(index) = usize::try_from(state_id) else {
        return &FULL_CUBE;
    };
    table()
        .and_then(|table| table.collision.get(index))
        .map_or(&FULL_CUBE, Vec::as_slice)
}

/// Outline (selection) boxes for a registry block-state id.
///
/// Unknown ids fall back to a full cube. Known passable states return an empty
/// slice for this slice's physics-focused policy.
pub fn outline_boxes(state_id: i32) -> &'static [Aabb] {
    let Ok(index) = usize::try_from(state_id) else {
        return &FULL_CUBE;
    };
    table()
        .and_then(|table| table.outline.get(index))
        .map_or(&FULL_CUBE, Vec::as_slice)
}

/// Collision boxes for a concrete [`BlockState`], resolved through the registry.
pub fn collision_boxes_for_state(state: &BlockState) -> &'static [Aabb] {
    collision_boxes(registry::block_state_id(state))
}

/// Outline boxes for a concrete [`BlockState`], resolved through the registry.
pub fn outline_boxes_for_state(state: &BlockState) -> &'static [Aabb] {
    outline_boxes(registry::block_state_id(state))
}

/// Whether a state has at least one non-degenerate collision box.
pub fn has_collision(state_id: i32) -> bool {
    collision_boxes(state_id)
        .iter()
        .any(|bounds| !bounds.is_empty())
}

/// Whether a concrete state has at least one non-degenerate collision box.
pub fn has_collision_state(state: &BlockState) -> bool {
    collision_boxes_for_state(state)
        .iter()
        .any(|bounds| !bounds.is_empty())
}

/// Number of loaded shape rows.
pub fn state_count() -> usize {
    table().map_or(0, |table| table.collision.len())
}

/// Parse failure, if the embedded table could not be loaded.
///
/// A missing table makes every lookup fall back to a full cube; callers that
/// need to distinguish that from real data can check this value.
pub fn load_error() -> Option<&'static str> {
    TABLE.get_or_init(parse).as_ref().err().map(String::as_str)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn state(name: &str, properties: &[(&str, &str)]) -> BlockState {
        BlockState {
            name: name.into(),
            properties: properties
                .iter()
                .map(|(key, value)| ((*key).into(), (*value).into()))
                .collect(),
        }
    }

    #[test]
    fn table_is_complete_and_dense() {
        assert_eq!(load_error(), None);
        assert_eq!(state_count(), STATE_COUNT);
        assert_eq!(collision_boxes(0), &[]);
        assert_eq!(outline_boxes(0), &[]);
        assert_eq!(state_count(), 29_671);
    }

    #[test]
    fn stone_is_a_full_cube() {
        assert_eq!(collision_boxes(1), &[Aabb::FULL]);
        assert_eq!(outline_boxes(1), &[Aabb::FULL]);
        assert!(has_collision(1));
        assert_eq!(
            collision_boxes_for_state(&state("minecraft:stone", &[])),
            &[Aabb::FULL]
        );
    }

    #[test]
    fn unknown_ids_fall_back_to_a_full_cube() {
        assert_eq!(collision_boxes(-1), &[Aabb::FULL]);
        assert_eq!(collision_boxes(1_000_000), &[Aabb::FULL]);
        assert_eq!(outline_boxes(1_000_000), &[Aabb::FULL]);
        assert!(has_collision(1_000_000));
    }

    #[test]
    fn passable_states_have_no_shapes() {
        for (name, properties) in [
            ("minecraft:air", &[][..]),
            ("minecraft:water", &[("level", "0")][..]),
            ("minecraft:short_grass", &[][..]),
        ] {
            let state = state(name, properties);
            assert!(
                collision_boxes_for_state(&state).is_empty(),
                "{name} should have no collision boxes"
            );
            assert!(
                outline_boxes_for_state(&state).is_empty(),
                "{name} should have no outline boxes"
            );
            assert!(!has_collision_state(&state));
        }
    }
}
